/**
 * Runs after `prisma migrate deploy` in the migration job (owner connection, DATABASE_URL):
 * lets the API's least-privilege role log in with APP_DB_PASSWORD. Idempotent.
 *   node dist/jobs/setup-db.js
 */
import { PrismaClient } from '@prisma/client';

async function main() {
  const password = process.env.APP_DB_PASSWORD ?? '';
  // generated by infra/azure/setup.sh; strict format, so it can be inlined safely below
  if (!/^[A-Za-z0-9]{24,128}$/.test(password))
    throw new Error('APP_DB_PASSWORD must be 24–128 letters/digits');
  const prisma = new PrismaClient();
  try {
    await prisma.$executeRawUnsafe(`ALTER ROLE seatline_app WITH LOGIN PASSWORD '${password}'`);
    console.log('seatline_app can log in');
  } finally {
    await prisma.$disconnect();
  }
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});
